package com.chickencenter.ui.controllers;import com.chickencenter.model.Sale;import com.chickencenter.model.PurchaseBatch;import com.chickencenter.service.BillingService;import com.chickencenter.service.ExpenseService;import com.chickencenter.service.StockService;import javafx.collections.FXCollections;import javafx.collections.ObservableList;import javafx.fxml.FXML;import javafx.scene.control.*;import java.sql.SQLException;import java.time.LocalDate;import java.util.List;public class ReportsController {    @FXML private DatePicker dpStartDate;    @FXML private DatePicker dpEndDate;    @FXML private Button btnGenerateReport;    @FXML private Label lblTotalSales;    @FXML private Label lblTotalPurchases;    @FXML private Label lblTotalExpenses;    @FXML private Label lblNetProfit;    @FXML private TableView<Sale> tblSalesReport;    @FXML private TableColumn<Sale, Integer> colSaleId;    @FXML private TableColumn<Sale, String> colSaleDate;    @FXML private TableColumn<Sale, Double> colSaleAmount;    @FXML private TableColumn<Sale, String> colSaleStatus;    private final BillingService billingService;    private final ExpenseService expenseService;    private final StockService stockService;    private final ObservableList<Sale> salesList;    public ReportsController() {        this.billingService = new BillingService();        this.expenseService = new ExpenseService();        this.stockService = new StockService();        this.salesList = FXCollections.observableArrayList();    }    @FXML    public void initialize() {        setupTable();        dpStartDate.setValue(LocalDate.now());        dpEndDate.setValue(LocalDate.now());        generateReport();    }    private void setupTable() {        tblSalesReport.setSelectionModel(null);        tblSalesReport.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY);                colSaleId.setCellValueFactory(cellData -> new javafx.beans.property.SimpleIntegerProperty(cellData.getValue().getId()).asObject());        colSaleDate.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().getSaleDate().toString()));        colSaleAmount.setCellValueFactory(cellData -> new javafx.beans.property.SimpleDoubleProperty(cellData.getValue().getTotalAmount()).asObject());        colSaleStatus.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().isBilled() ? "Billed" : "Pending"));        tblSalesReport.setItems(salesList);    }    @FXML    private void generateReport() {        LocalDate startDate = dpStartDate.getValue();        LocalDate endDate = dpEndDate.getValue();        if (startDate == null || endDate == null) {            showError("Please select date range");            return;        }        try {            salesList.clear();            salesList.addAll(billingService.getSalesByDateRange(startDate, endDate));            double totalSales = salesList.stream().mapToDouble(Sale::getTotalAmount).sum();            List<PurchaseBatch> purchases = stockService.getPurchasesByDateRange(startDate, endDate);            double totalPurchases = purchases.stream().mapToDouble(PurchaseBatch::getTotalAmount).sum();            double totalExpenses = expenseService.getTotalExpenses();            double netProfit = totalSales - totalPurchases - totalExpenses;            lblTotalSales.setText(String.format("Rs.%.2f", totalSales));            lblTotalPurchases.setText(String.format("Rs.%.2f", totalPurchases));            lblTotalExpenses.setText(String.format("Rs.%.2f", totalExpenses));            lblNetProfit.setText(String.format("Rs.%.2f", netProfit));            if (netProfit >= 0) {                lblNetProfit.setStyle("-fx-text-fill: #00b894;");            } else {                lblNetProfit.setStyle("-fx-text-fill: #d63031;");            }        } catch (SQLException e) {            showError("Error generating report: " + e.getMessage());        }    }    private void showError(String message) {        Alert alert = new Alert(Alert.AlertType.ERROR);        alert.setTitle("Error");        alert.setHeaderText(null);        alert.setContentText(message);        alert.showAndWait();    }}
